effect.shader:
void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    if (softness > 0.0) {
        vec4 s = vec4(0.0);
        for (int i = -2; i <= 2; i++) {
            s += texture(inputImg, acScreenNorm + vec2(0.0, float(i)) * softness * 0.5);
        }
        c = s * 0.2;
    }
    float linha = sin(acScreenNorm.y * count * 3.14159);
    float mdl = mix(1.0 - depth, 1.0, 0.5 + 0.5 * linha);
    fragColor = vec4(c.rgb * mdl, c.a);
}
